let colors_tone7 = "F2E96D-F2B84B-BF8034-402B12-0D0D0D".split("-").map((a) => "#" + a);
let colorsets = [colors_tone1, colors_tone2, colors_tone3, colors_tone4, colors_tone5, colors_tone6, colors_tone7];
let colorset;
let originalGraphics;
let t = 0;

function setup() {
  frameRate(60);
  mySize = 800;
  margin = mySize / 100;
  createCanvas(mySize, mySize);
  colorset = random(colorsets);
  originalGraphics = createGraphics(width, height);
  background("#fafdff");
}

function draw() {
  image(originalGraphics, 0, 0);

  // draw at mouse position
  let baseColor = color(random(colorset));
  baseColor.setAlpha(180);
  originalGraphics.push();
  originalGraphics.translate((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  originalGraphics.rotate(sin(t) * PI / 6);
  originalGraphics.fill(baseColor);
  originalGraphics.noStroke();
  let r = random(5, 20);
  originalGraphics.ellipse(0, 0, r, r);
  originalGraphics.pop();

  t += 0.02;
}


